SET NAMES utf8mb4;

DROP TABLE IF EXISTS `community_parking_record`;
CREATE TABLE `community_parking_record` (
  `record_id` bigint NOT NULL COMMENT '停车记录ID',
  `vehicle_id` bigint DEFAULT NULL COMMENT '车辆ID',
  `space_id` bigint DEFAULT NULL COMMENT '车位ID',
  `owner_id` bigint DEFAULT NULL COMMENT '业主ID',
  `community_id` bigint DEFAULT NULL COMMENT '小区ID',
  `plate_no` varchar(32) DEFAULT NULL COMMENT '车牌号',
  `in_time` datetime DEFAULT NULL COMMENT '入场时间',
  `out_time` datetime DEFAULT NULL COMMENT '出场时间',
  `parking_duration` int DEFAULT NULL COMMENT '停车时长（分钟）',
  `parking_fee` decimal(10,2) DEFAULT NULL COMMENT '停车费用',
  `pay_status` char(1) DEFAULT '0' COMMENT '支付状态（0未支付 1已支付）',
  `record_type` varchar(32) DEFAULT NULL COMMENT '记录类型（固定车 临停车）',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(1024) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`record_id`),
  KEY `idx_parking_record_vehicle_id` (`vehicle_id`),
  KEY `idx_parking_record_space_id` (`space_id`),
  KEY `idx_parking_record_owner_id` (`owner_id`),
  KEY `idx_parking_record_community_time` (`community_id`, `in_time`),
  KEY `idx_parking_record_plate_no` (`plate_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='停车记录表';

DROP TEMPORARY TABLE IF EXISTS `tmp_parking_record_ref`;
CREATE TEMPORARY TABLE `tmp_parking_record_ref` AS
SELECT (@rownum := @rownum + 1) AS rn, t.*
FROM (
  SELECT v.vehicle_id, ps.space_id, v.owner_id, v.plate_no, ps.space_type
  FROM `community_vehicle` v
  LEFT JOIN `community_parking_space` ps ON ps.vehicle_id = v.vehicle_id
  ORDER BY v.vehicle_id
  LIMIT 4
) t, (SELECT @rownum := 0) x;

